WITH lines AS (SELECT id, customer_id, attr_key, value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) x AS attr_key, value), cleaned AS (SELECT *, LENGTH(attr_key) AS attr_key_length, COALESCE(attr_key, 'DIRECT') AS attr_key_clean FROM lines WHERE customer_id IN (9, 17, 31)), kept_keys AS (SELECT customer_id FROM cleaned EXCEPT SELECT customer_id FROM carts WHERE TO_DATE(created_at) >= '2024-07-02'), verified AS (SELECT s.* FROM cleaned s INNER JOIN kept_keys k ON s.customer_id = k.customer_id), metrics AS (SELECT *, SUM(attr_key_length) OVER (PARTITION BY customer_id) AS customer_id_sum_attr_key_length, STDDEV_SAMP(attr_key_length) OVER (PARTITION BY customer_id) AS customer_id_stddev_samp_attr_key_length FROM verified), metrics_carts AS (SELECT *, MAX(attr_key_length) OVER (PARTITION BY attr_key, customer_id) AS attr_key_max_attr_key_length, CUME_DIST() OVER (PARTITION BY attr_key, customer_id ORDER BY customer_id_stddev_samp_attr_key_length DESC NULLS LAST) AS customer_id_stddev_samp_attr_key_length_cume_dist, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY customer_id_stddev_samp_attr_key_length DESC NULLS FIRST) AS customer_id_stddev_samp_attr_key_length_dense_rank FROM metrics) SELECT id, customer_id, value, attr_key_length, attr_key_clean, customer_id_sum_attr_key_length, customer_id_stddev_samp_attr_key_length_cume_dist FROM metrics_carts
